String.prototype.trim = function() {
	return this.replace(/^[ 　]*/gim, '').replace(/[ 　]*$/gim, '');
}

jQuery(function() {
	// 数値入力制限
	// (正数のみ)
	$('.numeric').numeric();

	// (小数点以下の入力可)
	$('.numeric_decimal').numeric({
		allow : "."
	});

	// (負数も入力可)
	$('.numeric_minus_price').numeric({
		allow : "-"
	});

	$.fn._ng_input_check_ = function(){
		return this.each (function(){
			$(this).keypress (
					function(e) {
						if (   (e.which && (e.which == 92 || e.which == 34 || e.which == 39 || e.which == 44 || e.which == 60 || e.which == 62 || e.which == 38))
								|| (e.charCode && (e.charCode == 92 || e.charCode == 34 || e.charCode == 39 || e.charCode == 44 || e.charCode == 60 || e.charCode == 62 || e.charCode == 38))
							) {
							alert("半角文字の「\\」「'」「\"」「,」「<」「>」「&」は利用できません。");
							return false;
						} else {
							return true;
