function getFormParam(formname) {
	var formParam = {};
	var input_element = $("form[name=" + formname + "]").find("input");
	for (var i = 0; i < input_element.length; i++) {
		setParam(input_element[i]);
	}
	return formParam;

	function setParam(element) {
		switch (element.type) {
		// 配列ではない値
		case 'text':
		case 'hidden':
			formParam[element.name] = $("input[name='" + element.name + "']")
					.val();
			break;
		case 'radio':
			formParam[element.name] = $(
					"input[name='" + element.name + "']:checked").val();
			break;
		case 'checkbox':
			var check_name = element.name.replace(/\[\]/g, '');
			if (formParam[check_name] !== undefined) {
				break;
			}
			formParam[check_name] = {};
			// Checked判定
			var count = 0;
			$("input[name='" + element.name + "']:checked").each(function() {
				formParam[check_name][count] = $(this).val();
				count++;
			});
			break;
		default:
			break;
		}

	}
}

