// ラジオボタンと入力項目のDisabled制御
function checkInputDisabled() {
	var search_element = $(":radio , :checkbox");
	for (var i = 0; i < search_element.length; i++) {
		var className = $(search_element[i]).attr('class');
		if ($(search_element[i]).is(':checked')) {
			if (className == null) {
				$(search_element[i]).parent().find("select").removeAttr(
						"disabled");
				$(search_element[i]).parent().find("select").children()
						.removeAttr("disabled");
				$(search_element[i]).parent().find(".disabled").not("select")
						.removeAttr("disabled");
			} else {
				$("#" + className + " .disabled").removeAttr("disabled");
			}
		} else {
			if (className == null) {
				$(search_element[i]).parent().find(".disabled").not(
						"text,option").val("");
				$(search_element[i]).parent().find(".disabled").not(
						"select,option").val("");
				$(search_element[i]).parent().find(".disabled").attr("checked",
						false);
				$(search_element[i]).parent().find(".disabled").attr(
						"disabled", "disabled");
			} else {
				$("#" + className + " .disabled").val("");
				$("#" + className + " .disabled").attr("disabled", "disabled");
			}
		}
	}
}

