										 */
										$form
												.find("input[type=file]")
												.each(
														function() {
															file_field_name = $(
																	this).attr(
																	"name");
															file_value = $(this)
																	.val();

															if ($
																	.trim(file_value) != "") {
																// ファイル名のみ抜き出し
																var regex = /\\|\\/;
																var array = file_value
																		.split(regex);
