																// チェックボックスを表示
																$(this)
																		.prev(
																				"div")
																		.prepend(
																				'<input type="checkbox" name="delete_file[]" value="'
																						+ filename
																						+ '" class="onecheck" />');
																// ファイル名をファイルの代わりにラベルにする
																$(this)
																		.before(
																				"<span id='"
