function none_check_mailfax_common(msg, nextMsg, nextFunc, secondFunc, findName, pdfFlag){
	if(checkCheckOnly(msg, nextMsg, nextFunc, secondFunc, findName))
	{
		var form = $("form[id=executeForm]");
		var oneChecks = form.find("." + findName);
		var count = oneChecks.length;

		var check_flag = false;

		for (i = 0; i < count; i++) {
			// チェックされているか確認する
			if (oneChecks.eq(i).is(":checked")) {
				//チェックが入っているデータの、送信方法が選択されているか
				oneChecks.eq(i).parent("td").prev("td").find(".soshin_hoho_type").each(function(){
					//チェックしてあるか
					if($(this).is(":checked")){
						check_flag = true;
					}
				});
			}
		}

		if(check_flag == false){
			return nextFunc(nextMsg, secondFunc);
		}

		var confirmResult = nextFunc(nextMsg);

		//確認ダイアログ出してOK
		if(confirmResult == true && pdfFlag == true){
			openPDFDownloadWindow();
		}

		if(confirmResult == true){
			secondFunc(nextMsg);
			return true;
		}

		return confirmResult;
	}
	else{
		return false;
	}
}

