function getFormData(formname) {
	var fd;
	var input_element = $("form[name=" + formname + "]").find("input");
	for (var i = 0; i < input_element.length; i++) {
		// テキストデータおよびアップロードファイルが設定されていれば追加
		if (input_element[i].type == "file") {
			if ($("input[name='" + input_element[i].name + "']").val() !== '') {
				fd.append(input_element[i].name, $("input[name='"
						+ input_element[i].name + "']"));
			}
		}

	}

	return fd;
}

function getFormParam(formname) {
	var formParam = {};
	var input_element = $("form[name=" + formname + "]").find("input");
	for (var i = 0; i < input_element.length; i++) {
		setParam(input_element[i]);
	}
	return formParam;

	function setParam(element) {
		switch (element.type) {
		// 配列ではない値
		case 'text':
		case 'hidden':
			formParam[element.name] = $("input[name='" + element.name + "']")
					.val();
			break;
		case 'radio':
			formParam[element.name] = $(
					"input[name='" + element.name + "']:checked").val();
			break;
		case 'checkbox':
			var check_name = element.name.replace(/\[\]/g, '');
			if (formParam[check_name] !== undefined) {
				break;
			}
			formParam[check_name] = {};
			// Checked判定
			var count = 0;
			$("input[name='" + element.name + "']:checked").each(function() {
				formParam[check_name][count] = $(this).val();
				count++;
			});
			break;
		default:
			break;
		}

	}
}

function set_field(name, val) {
	$("#" + name).val(val);
}

function setOnEnterClickButton() {
	var form = document.forms[0];
	var targetButton = jQuery('.enter_press');
	document.onkeypress = function(e) {
		e = e ? e : event;
		var keyCode = e.charCode ? e.charCode : ((e.which) ? e.which
				: e.keyCode);
		var elem = e.target ? e.target : e.srcElement;
		if (Number(keyCode) == 13) {// 13=EnterKey
			if (!isIgnoreEnterKeySubmitElement(elem)) {
				targetButton.click();
			}
			return isInputElement(elem) ? false : true;
		}
	}
}

function isIgnoreEnterKeySubmitElement(elem) {
	var tag = elem.tagName;
	if (tag.toLowerCase() == "textarea") {
		return true;
	}
	if (elem.id == 'partnerSelectTable:globalFilter') {
		return true;
	}

	switch (elem.type) {
	case "button":
	case "submit":
	case "reset":
	case "image":
	case "file":
		return true;
	}
	return false;
}
function isInputElement(elem) {
	switch (elem.type) {
	case "text":
	case "radio":
	case "checkbox":
	case "password":
		return true;
	}
	return false;
}

