function oneCheck() {
	var count = $(".onecheck").length;
	var allcheck = document.getElementById("allcheck");

	// いずれかがチェックされているか
	var existChaecked = false;
	// 全てチェックが外れているか
	var existNoChecked = false;

	// Checked判定
	for (var i = 0; i < count; i++) {
		if (!$(".onecheck").eq(i).is(":checked")) {
			// いずれかがCheck ON
			existNoChecked = true;
		} else {
			// いずれかがCheck OFF
			existChaecked = true;
		}
	}

	// 全Check判定
	if (existNoChecked) {
		// Checkなしが存在する場合
		if (existChaecked) {
			// 部分的にCheckされている
			allcheck.indeterminate = true;
		} else {
			// 全Checkなし
			allcheck.indeterminate = false;
			allcheck.checked = false;
		}

	} else {
		// Checkなしが存在しない場合
		if (existChaecked) {
			// 全Checkあり
			allcheck.indeterminate = false;
			allcheck.checked = true;
		}
	}

}

