function delShohinMeisai(obj) {
	var meisaiCount = $("#meisaiList").find(".shohinMeisaiItem").size();
	if (meisaiCount == 1) {
		return false;
	}

	$(obj).parents(".shohinMeisaiItem").remove();

	var count = 0;
	$("#meisaiList").find(".shohinMeisaiItem").each(function() {
		var obj = $(this);
		replaceShohinMeisaiAttribute($(this), count);
		count++;
		obj = null;
	});

	if (count == 1) {
		$(".meisaidel").hide();
	}

	return false;
}

function replaceShohinMeisaiAttribute(obj, meisaiCount) {
	obj.find("input").each(
			function() {
				var elem = $(this);
				var id = elem.attr("id");
				var name = elem.attr("name");
				if (name !== undefined
						&& name.indexOf("data[ShohinMeisaiList]") !== -1) {
					name = name.replace(/\d{1,5}/g, meisaiCount);
					elem.attr("name", name);
					name = null;
				}

				if (id !== undefined
						&& id.indexOf("data_ShohinMeisaiList__") !== -1) {
					id = id.replace(/__\d{1,5}__/g, "__" + meisaiCount + "__");
					elem.attr("id", id);
				}


				elem = null;
			});

	obj.find("label").each(
			function() {
				var forAttr = $(this).attr("for");
				if (forAttr !== undefined
						&& forAttr.indexOf("data_ShohinMeisaiList__") !== -1) {
					forAttr = forAttr.replace(/__\d{1,5}__/g, "__" + meisaiCount
							+ "__");
					$(this).attr("for", forAttr);
				}

			});

	obj = null;

}

