	var count = 0;
	$("#CalendarBlockList").find(".CalendarBlockItem").each(
			function() {
				if ($(this).find(".delBlock").prop('checked')) {
					var meisaiCount = $("#CalendarBlockList").find(
							".CalendarBlockItem").size();
					if (meisaiCount == 1) {
						$(this).find("input").val("");
						$(this).find(".delBlock").prop("checked", false);
						replaceCalendarBlockAttribute($(this), count);
						count++;
