function updateKokaiSet() {
	// ボタンの無効
	$("#cboxLoadedContent :button").attr("disabled", "disabled");

	// post送信用に、colorox内のフォームでinputのデータを設定
	var postData = {};
	$("#cboxLoadedContent").find(':input').each(
			function() {
				if ($(this).attr('type') == 'radio'
						|| $(this).attr('type') == "checkbox") {
					// ラジオボタンの場合
					if ($(this).is(':checked')) {
						postData[$(this).attr('name')] = $(this).val();
					}
				} else {
					postData[$(this).attr('name')] = $(this).val();
				}

			});

	// 設定
	var opts = {
		lines : 9, // 線の数
		length : 10, // 線の長さ
		width : 6, // 線の幅
		radius : 8, // スピナーの内側の広さ
		corners : 1, // 角の丸み
		color : '#000', // 色
		speed : 1, // 一秒間に回転する回数
		trail : 60, // 残像の長さ
		shadow : true, // 影
		className : 'spinner', // クラス名
		zIndex : 99999, // Z-index
		top : '50%', // relative TOP
		left : '50%', // relative LEFT
		opacity : .15
	// 透明度
	};

	/**
	 * スピナー
	 */
	// 描画先の親要素
	var target = $("#cboxLoadedContent #kokaicontent").get(0);
	// スピナーオブジェクト
	var spinner = new Spinner(opts).spin(target);

	// スピナーの起動
	spinner.spin(target);

	$
			.ajax({
				type : 'post',
				url : "/spmain/master/shohin/shohin_search/kokaiValidate",
				data : postData,
				success : function(data) {
					$("#cboxLoadedContent").html(data);

					// エラーチェックにひっかかっていない場合は登録処理をajaxで行う
					if ($("#cboxLoadedContent #is_error").val() != "1") {
						// HTMLが入れ替わるため、ボタンの無効とスピナーの再起動
						$("#cboxLoadedContent :button").attr("disabled",
								"disabled");
						target = $("#cboxLoadedContent #kokaicontent").get(0);
						spinner.spin(target);

						$
								.ajax({
									type : 'post',
									url : "/spmain/master/shohin/shohin_search/update_kokai_set",
									data : postData,
									success : function(data) {
										spinner.stop();
										closeColorBox(null);
										$("#executeForm").html(data);
									},
									error : function(XMLHttpRequest,
											textStatus, errorThrown) {
										spinner.stop();
										closeColorBox(null);
										$("#executeForm").html(
												XMLHttpRequest.responseText);
									}
								});
					}
				}
			});

	return false;
}

