	$.fn._ng_input_check_ = function(){
		return this.each (function(){
			$(this).keypress (
					function(e) {
						if (   (e.which && (e.which == 92 || e.which == 34 || e.which == 39 || e.which == 44 || e.which == 60 || e.which == 62 || e.which == 38))
							|| (e.charCode && (e.charCode == 92 || e.charCode == 34 || e.charCode == 39 || e.charCode == 44 || e.charCode == 60 || e.charCode == 62 || e.charCode == 38))
							) {
							alert("半角文字の「\\」「'」「\"」「,」「<」「>」「&」は利用できません。");
							return false;
						} else {
							return true;
						}
					}
				);

			$(this).change (
					function() {
						if ($(this).val().match(/\\/) || $(this).val().match(/'/) || $(this).val().match(/"/) || $(this).val().match(/,/) || $(this).val().match(/</) || $(this).val().match(/>/) || $(this).val().match(/&/)) {
							var str = $(this).val().replace(/\\/g, "");
							str = str.replace(/'/g, "");
							str = str.replace(/\"/g, "");
							str = str.replace(/,/g, "");
							str = str.replace(/</g, "");
							str = str.replace(/>/g, "");
							str = str.replace(/&/g, "");
							$(this).val(str);
							alert("半角文字の「\\」「'」「\"」「,」「<」「>」「&」は利用できません。");
							return false;
						} else {
							return true;
						}
					}
				);
		});
	};

	var form = document.forms[0];
	if (form && form._input_check_ != true) {
		form._input_check_ = true;

		// 全テキスト
		$('input[type=text]')._ng_input_check_();
		$('textarea').not('.not_ng_input_check')._ng_input_check_();
	}

