function file_upload_change(this_file) {
	file_field_name = $(this_file).attr("name");
	file_value = $(this_file).val();

	if ($.trim(file_value) != "") {
		// ファイル名のみ抜き出し
		var regex = /\\|\\/;
		var array = file_value.split(regex);
		var this_filename = array[array.length - 1];
	}

	var parent = $(this_file).parent().parent().parent().parent();
	parent.find(".upfile").each(
			function() {
				var tag = $(this).get(0).tagName;
				if (tag == "SPAN") {
					check_filename = $(this).text();
					check_field_name = $(this).attr("id");
				} else {
					check_field_name = $(this).attr("name");
					file_value = $(this).val();
					regex = /\\|\\/;
					array = file_value.split(regex);
					check_filename = array[array.length - 1];
				}

				// ファイル名の不正チェック
				var lower_this_filename = this_filename.toLowerCase();
				if (lower_this_filename.indexOf('/') != -1
						|| lower_this_filename.indexOf('%2f') != -1
						|| lower_this_filename.indexOf('\\') != -1
						|| lower_this_filename.indexOf('%5c') != -1
						|| lower_this_filename.indexOf('%00') != -1) {
					alert("ファイル名に「/、%2f、%00、%5c、\\」は使用できません。");

					// 重複しているなら現在選択中のフィールドを空にする
					if ($(this_file).parent().attr("class") == "clear_form") {
						$(this_file).parent().get(0).innerHTML = $(this_file)
								.parent().get(0).innerHTML;
					}
					return false;
				}

				// ファイル名の長さチェック
				var file_name_length = $(".fileNameLength").val();
				if (lower_this_filename.length > file_name_length) {
					alert("ファイル名が"+file_name_length+"文字を超えています。");

					// 重複しているなら現在選択中のフィールドを空にする
					if ($(this_file).parent().attr("class") == "clear_form") {
						$(this_file).parent().get(0).innerHTML = $(this_file)
								.parent().get(0).innerHTML;
					}
					return false;
				}

				// 自分以外のファイル名が重複していないかどうかをチェックする
				if (check_filename == this_filename
						&& check_field_name != file_field_name) {
					alert("ファイル名が他のファイルと重複しています。");
					// 重複しているなら現在選択中のフィールドを空にする
					// $(this_file).val("");
					if ($(this_file).parent().attr("class") == "clear_form") {
						$(this_file).parent().get(0).innerHTML = $(this_file)
								.parent().get(0).innerHTML;
					}
					return false;
				}
			});

	// 拡張子チェック
	parent
			.find(".upfile_extension_check")
			.each(
					function() {
						extension_field_name = $(this).attr("name");
						if (file_field_name == extension_field_name) {
							extension = $(this).val();

							if (extension == "*" || extension == "") {
							} else {
								regex = /\./;
								array = this_filename.split(regex);
								check_extension = array[array.length - 1];

								// 拡張子チェック
								var re = new RegExp(extension, "i");
								if (check_extension.match(re) === null) {

									$(".upfile")
											.each(
													function() {
