/** **********ファイル削除ボタンクリックイベント************** */
function file_delete_button_event(_formName, _sendURL) {

	// 設定
	var opts = {
		lines : 9, // 線の数
		length : 10, // 線の長さ
		width : 6, // 線の幅
		radius : 8, // スピナーの内側の広さ
		corners : 1, // 角の丸み
		color : '#000', // 色
		speed : 1, // 一秒間に回転する回数
		trail : 60, // 残像の長さ
		shadow : true, // 影
		className : 'spinner', // クラス名
		zIndex : 99999, // Z-index
		top : '50%', // relative TOP
		left : '50%', // relative LEFT
		opacity : .15
	// 透明度
	};

	/**
	 * スピナー
	 */
	// 描画先の親要素
	var target = $('#file-upload-content').get(0);
	// スピナーオブジェクト
	var spinner = new Spinner(opts).spin(target);

	// スピナーの起動
	spinner.spin(target);

	// 送信データ
	var send_data = getFormParam(_formName);

	// 送信URL
	var send_url = _sendURL;

	// ボタン無効化
	$(".disable_btn").prop("disabled", true);

	// 成功時のイベント
	var success = function(data) {
		$form = $("form[name='" + _formName + "']");

		$form.find("input[type=checkbox]").each(
				function() {
					if ($(this).is(':checked') == true) {
						var addfile_id = $(this).parent("div").nextAll("span")
								.slice(0, 1).attr("id");

						$(this).parent("div").after(
								'<input type="file" name="' + addfile_id
										+ '" />&nbsp<input type="button" class="disable_btn" value="クリア" onclick="$(this).parent().get(0).innerHTML = $(this).parent().get(0).innerHTML;">');
						$(this).parent("div").next("span").insertBefore(
								'#addfile_id');
						$(this).parent("div").nextAll("span").slice(0, 1)
								.remove();
						$(this).remove();
					}
				});

		// 返ってきた値を変更
		$("#uploaded_file").html(data);

		// 再描画用Itemが設定されていれば
		successRedraw = $form.find("input[name=isSuccessRedrawItem]");
		if (successRedraw.length) {
			// レスポンスデータの画面への反映
			isSuccessRedrawItem = successRedraw.val();
			$(isSuccessRedrawItem).html(data);
		}

		$("#file_upload_open").colorbox.close();

		spinner.stop();

		// ボタン有効化
		$(".disable_btn").prop("disabled", false);

	}

	// ajax通信
	ajaxEvent(send_url, send_data, success)

	return false;
}
/** *****************ajaxイベント**************************** */
function ajaxEvent(url, data, success_handler, error_handler) {

	// 各イベントを指定していない場合
	if (typeof success_handler == "undefined") {
		success_handler = function() {
			return false;
		}
	}
	if (typeof error_handler == "undefined") {
		error_handler = function() {
			return false;
		}
	}

	$.ajax({
		type : 'post',
		url : url,
		data : data,
		success : success_handler,
		error : error_handler,
		complete : function(MLHttpRequest, textStatus) {
		}
	});

}
