var GenreCategorySelectTpl = [];
// 表示
function openGenreCategorySelect(type, obj_name, search, mode) {

	var sel_genre = [];
	var sel_category = [];
	var name_genre_code = "genre_code";
	var name_category_code = "category_code";
	var search_element = $("." + obj_name + "_genre_category").children().find(
			"input");

	for (var i = 0; i < search_element.length; i++) {
		if (search_element[i].type == "hidden") {
			if (search_element[i].name.indexOf("data[" + obj_name
					+ "_genre_code]") != -1) {
				sel_genre.push(search_element[i].value);
			}
			if (search_element[i].name.indexOf("data[" + obj_name
					+ "_category_code]") != -1) {
				sel_category.push(search_element[i].value);
			}
			if (search_element[i].name.indexOf("data[" + obj_name
					+ "_hasso_code]") != -1) {
				sel_category.push(search_element[i].value + "HASSO");
			}
		}
	}

	if (type == "checkbox") {
		name_genre_code = name_genre_code + "[]";
		name_category_code = name_category_code + "[]";
	}

	if (GenreCategorySelectTpl["\"" + obj_name + "\""] != null
			&& GenreCategorySelectTpl["\"" + obj_name + "\""].length != 0) {
		$
				.colorbox({
					maxWidth : "1100px",
					height : "600px",
					html : GenreCategorySelectTpl["\"" + obj_name + "\""],
					inline : false,
					onComplete : function() {
						var ele_genre = $("#cboxLoadedContent [name='"
								+ name_genre_code + "']");
						for (var g = 0; g < ele_genre.length; g++) {
							if (ele_genre[g].type == type
									&& sel_genre.indexOf(ele_genre[g].value) >= 0) {

								ele_genre[g].checked = true;
							}
						}

						var ele_category = $("#cboxLoadedContent [name='"
								+ name_category_code + "']");
						for (var c = 0; c < ele_category.length; c++) {

							if (ele_category[c].type == type
									&& sel_category
											.indexOf(ele_category[c].value) >= 0) {
								ele_category[c].checked = true;
							}
						}
					}
				});

	} else {
		$
				.colorbox({
					maxWidth : "1100px",
					height : "600px",
					href : "/spmain/common/genre_category_hasso_type_select/ini/"
							+ type + "/" + obj_name + "/" + search + "/" + mode + "?rnd_param=" + Math.random(),
					inline : false,
					onComplete : function() {
						// $("#cboxLoadedContent").toggle();
						if (sel_genre.length > 0) {
							$("#cboxLoadedContent #category_spiner").show();

							var ele_genre = $("#cboxLoadedContent [name='"
									+ name_genre_code + "']");
							for (var g = 0; g < ele_genre.length; g++) {
								if (ele_genre[g].type == type
										&& sel_genre
												.indexOf(ele_genre[g].value) >= 0) {

									ele_genre[g].checked = true;
								}
							}

							$
									.ajax({
										type : 'post',
										url : "/spmain/common/genre_category_hasso_type_select/selected_genre",
										data : {
											'type' : type,
											'search' : search,
											'mode' : mode,
											'params' : getFormParam("selected")
										},
										success : function(data) {
											$(
													"#cboxLoadedContent #category_spiner")
													.hide();
											$("#" + type + "_genre_category")
													.html(data);
											var ele_category = $("#cboxLoadedContent [name='"
													+ name_category_code + "']");
											for (var c = 0; c < ele_category.length; c++) {

												if (ele_category[c].type == type
														&& sel_category
																.indexOf(ele_category[c].value) >= 0) {
													ele_category[c].checked = true;
												}
