function addShohinMeisai() {

	var meisaiCount = $("#meisaiList").find(".shohinMeisaiItem").size();
	if (meisaiCount == 99) {
		return false;
	}

	var meisaiLast = $("#meisaiList .shohinMeisaiItem:last-child");

	var meisaiLastClone = meisaiLast.clone();

	var entriedMeisaiCode = meisaiLastClone
			.find("input[type='textbox'][name $= '[ShohinMeisai][shohin_meisai_code]']")

	if (entriedMeisaiCode.size() == 0) {
		var meisaiCodeItem = meisaiLastClone
				.find("input[type='hidden'][name $= '[ShohinMeisai][shohin_meisai_code]']:first");
		var textItem = $("<input type=\"text\" maxlength=\"15\" style=\"width:130px;ime-mode:disabled;\" >");
		textItem.attr("name", meisaiCodeItem.attr("name"));
		textItem.val(meisaiCodeItem.val());
		var itemParent = meisaiCodeItem.parent();
		itemParent.html('');
		itemParent.append(textItem);
	}

	var entriedZaikoKanriyoMeisaiCode = meisaiLastClone
			.find("input[type='textbox'][name $= '[ShohinMeisai][zaiko_kanriyo_shohin_meisai_code]']")

	if (entriedZaikoKanriyoMeisaiCode.size() == 0) {
		var meisaiCodeItem = meisaiLastClone
				.find("input[type='hidden'][name $= '[ShohinMeisai][zaiko_kanriyo_shohin_meisai_code]']:first");
		var textItem = $("<input type=\"text\" maxlength=\"15\" style=\"width:130px;ime-mode:disabled;\" >");
		textItem.attr("name", meisaiCodeItem.attr("name"));
		textItem.val(meisaiCodeItem.val());
		var itemParent = meisaiCodeItem.parent();
		itemParent.html('');
		itemParent.append(textItem);
	}

	replaceShohinMeisaiAttribute(meisaiLastClone, meisaiCount);

	meisaiLastClone.find("input[type=text]")._ng_input_check_();

	// ラジオボタンを有効化
	meisaiLastClone.find("input[type='radio']").removeAttr("disabled");
	meisaiLastClone.find("input").css("visibility", "");
	meisaiLast.after(meisaiLastClone);

	// 削除ボタン表示
	$(".meisaidel").show();

	return false;
}

function delShohinMeisai(obj) {
	var meisaiCount = $("#meisaiList").find(".shohinMeisaiItem").size();
	if (meisaiCount == 1) {
		return false;
	}

	$(obj).parents(".shohinMeisaiItem").remove();

	var count = 0;
	$("#meisaiList").find(".shohinMeisaiItem").each(function() {
		var obj = $(this);
		replaceShohinMeisaiAttribute($(this), count);
		count++;
		obj = null;
	});

	if (count == 1) {
		$(".meisaidel").hide();
	}

	return false;
}

function replaceShohinMeisaiAttribute(obj, meisaiCount) {
	obj.find("input").each(
			function() {
				var elem = $(this);
				var id = elem.attr("id");
				var name = elem.attr("name");
				if (name !== undefined
						&& name.indexOf("data[ShohinMeisaiList]") !== -1) {
					name = name.replace(/\d{1,5}/g, meisaiCount);
					elem.attr("name", name);
					name = null;
				}

				if (id !== undefined
						&& id.indexOf("data_ShohinMeisaiList__") !== -1) {
					id = id.replace(/__\d{1,5}__/g, "__" + meisaiCount + "__");
					elem.attr("id", id);
				}


				elem = null;
			});

	obj.find("label").each(
			function() {
				var forAttr = $(this).attr("for");
				if (forAttr !== undefined
						&& forAttr.indexOf("data_ShohinMeisaiList__") !== -1) {
					forAttr = forAttr.replace(/__\d{1,5}__/g, "__" + meisaiCount
							+ "__");
					$(this).attr("for", forAttr);
				}

			});

	obj = null;

}

/** *********** カレンダー登録・更新 ブロック追加削除 ************ */
function addCalendarBlock() {

	var itemCount = $("#CalendarBlockList").find(".CalendarBlockItem").size();
	if (itemCount == 99) {
		return false;
	}

	var itemLast = $("#CalendarBlockList .CalendarBlockItem:last-child");
	var itemLastClone = itemLast.clone();

	replaceCalendarBlockAttribute(itemLastClone, itemCount);

	itemLastClone.find("input[type=text]")._ng_input_check_();

	// Check有効化
	itemLastClone.find("input").css("visibility", "");
	itemLast.after(itemLastClone);

	$(".delBlock").show();

	return false;
}

function delCalendarBlock() {
	var count = 0;
	$("#CalendarBlockList").find(".CalendarBlockItem").each(
			function() {
				if ($(this).find(".delBlock").prop('checked')) {
					var meisaiCount = $("#CalendarBlockList").find(
							".CalendarBlockItem").size();
					if (meisaiCount == 1) {
						$(this).find("input").val("");
						$(this).find(".delBlock").prop("checked", false);
						replaceCalendarBlockAttribute($(this), count);
						count++;
					} else {
						$(this).remove();
					}
				} else {
					replaceCalendarBlockAttribute($(this), count);
					count++;
				}
			});

	if (count == 1) {
		$(".delBlock").hide();
	}

	return false;
}

function replaceCalendarBlockAttribute(obj, itemCount) {
	obj.find("input,select").each(
			function() {
				var id = $(this).attr("id");
				var name = $(this).attr("name");
				if (name !== undefined
						&& name.indexOf("data[CalendarBlockList]") !== -1) {
					name = name.replace(/\d/g, itemCount);
					$(this).attr("name", name);
				}
				if (id !== undefined
						&& id.indexOf("data_CalendarBlockList__") !== -1) {
					id = id.replace(/__\d__/g, "__" + itemCount + "__");
					$(this).attr("id", id);
				}
			});

	obj.find("label").each(
			function() {
				var forAttr = $(this).attr("for");
				if (forAttr !== undefined
						&& forAttr.indexOf("data_CalendarBlockList__") !== -1) {
					forAttr = forAttr.replace(/__\d__/g, "__" + itemCount
							+ "__");
					$(this).attr("for", forAttr);
				}

			});

}

