/** *********** location.href等で遷移する際にIEの場合REFERERがセットされないので、その回避対応 ************ */
function redirect(url) {
	if (/MSIE (\d+\.\d+);/.test(navigator.userAgent)) {
		var referLink = document.createElement('a');
		referLink.href = url;
		document.body.appendChild(referLink);
		referLink.click();
	} else {
		location.href = url;
	}
}

