	if ($(obj).prop('checked')) {
		// チェックされてる
		// 同じ行の封入物A～Eを表示する
		$(obj).parents("tr").find("span").addClass("yoyaku_on");
		$(obj).parents("tr").find("span").removeClass("yoyaku_off");
		// 全てチェックをはずす
		$(obj).parents("tr").find("input[type=checkbox].yoyaku_on").prop(
				"checked", false);
		// 備考のテキストエリアをはずす
		$(obj).parents("tr").find("input[type=text]").val("");
	} else {
		// チェックをはずされた
		$(obj).parents("tr").find("span").addClass("yoyaku_off");
		$(obj).parents("tr").find("span").removeClass("yoyaku_on");
		// 全てチェックをはずす
		$(obj).parents("tr").find("input[type=checkbox]")
				.prop("checked", false);
		$(obj).parents("tr").find("input[type=checkbox].yoyaku_off").prop(
				"checked", false);
		// 備考のテキストエリアをはずす
		$(obj).parents("tr").find("input[type=text]").val("");
	}
}

