@charset "utf-8";

/*======================リンク色の設定======================*/

a{/*リンクされた文字*/
    color: #436fca;
	text-decoration:none;
}
a:link {/*未訪問のリンク*/
    color:#436fca;
	text-decoration:none;
}
a:visited {/*訪問後のリンク*/
    color: #436fca;
	text-decoration:none;
}
a:hover {/*マウスをのせたとき*/
    color:#436fca;
	text-decoration:underline;
}
a:active {/*クリック中*/
	text-decoration:underline;
