@CHARSET "UTF-8";

/**--ファイルが見つからなかったとき-- **/
.nodata{
	color: red;
	text-align:center;
}

/**--エラーメッセージエリア--*/
.error_area{
	width: 100%;
	padding: 20px;
	border: 3px solid #ea3232;
}
/** --エラーフィールド(赤枠)--*/
.error_field{
	border:3px solid #ea3232 !important;
	padding:4px;
}

.error_field_right_none{
	border-top-style:solid !important;
	border-top-width:2px !important;
	border-top-color:#ea3232 !important;

	border-bottom-style:solid !important;
	border-bottom-width:2px !important;
	border-bottom-color:#ea3232 !important;

	border-left-style:solid !important;
	border-left-width:2px !important;
	border-left-color:#ea3232 !important;

	padding:4px;
}

.error_field_left_none{
	border-top-style:solid !important;
	border-top-width:2px !important;
	border-top-color:#ea3232 !important;

	border-bottom-style:solid !important;
	border-bottom-width:2px !important;
	border-bottom-color:#ea3232 !important;

	border-right-style:solid !important;
	border-right-width:2px !important;
	border-right-color:#ea3232 !important;

	padding:4px;
}

.error_field_free_word_textbox{
	border:1px solid #ea3232 !important;
	padding:4px;
}
.error_message{
	color:#ea3232;
}

/** -- 商品一覧コメント --**/
.productCmt{
	padding: 2px 4px;
	margin: 0 0 5px 0;
	background-color: #ea3232;
	color: #fff;
}

/** --数値入力--*/
/*.numeric .numeric_decimal .numeric_minus_price{*/
.numeric{
	ime-mode: disabled;
}

.price{
	text-align: right;
}

/**文字を太文字にする**/
.bold{
	font-weight:bold;
}

.noborder{
	border:none !important;
}

.meisai_zaiko_comment{
	background-color: #FFC0CB !important;
	color: #000 !important;
	text-align: right !important;
}

/* 管理メニューの大項目メニュー */
.menu_title{
	text-align:left;
	background-color:gray;
	margin:0px 0px 10px 0px;
	padding: 2px;
	font-weight:bold;
	color: #fff;
}

/* 管理メニューのサブタイトル */
.menu_subtitle{
	width: 400px;
	height: 20px;
	display:block;
	margin-bottom: 10px;
	margin-top:10px;
}

.menu_subtitle:before{
	content: " "; /*これは大事なので消さないで*/
	background-color:#00FFFF;
	vertical-align: middle;
	display: inline-block;
	height: 20px;
	width: 10px;
	margin-right: 10px;
	border: 1px solid #000000;
}

/*左側のメニュー*/
.menu_left_box{
	width:430px;
	float:left;
	margin:0px 0px 10px 0px;
}

.menu_left_box_list{
	border: 1px solid #000000;
	padding-left: 20px;
	padding-top: 5px;
	padding-bottom:5px;
}
.menu_list li{
	margin-left:0px;
	list-style-type: none;
	padding: 2px;
}

/*右側のメニュー*/
.menu_right_box{
	width: 430px;
	/*margin-left: 10px;*/
	float:left;
	margin:0px 0px 10px 10px;
}
.menu_box_list{
	border: 1px solid #000000;
	padding-left: 20px;
	padding-top: 5px;
	padding-bottom:5px;
}
.menu_right_box:after{
	clear:both;
}

.completeAd{
	display:block;
	color:#00b400;
	font-size:129%;
	font-weight:bold;
	line-height:1.5;
	border:2px solid #00b400;
	text-align: left;
	margin:0 0 20px 0;
	padding:20px 10px;
}

.completeAd li{
	list-style: disc;
	color:#00b400;
	margin-left:35px;

}


/*カートコメント行が出ているCSS*/
.cart_zaiko_comment td{
	background-color: #FFC0CB !important;
}

